import React, { useState } from "react";
import { View, StyleSheet, ScrollView, KeyboardAvoidingView, Platform } from "react-native";
import { Provider as PaperProvider, Text, TextInput, Button, Modal, Portal, Snackbar, Card } from "react-native-paper";

export default function App() {
  const [peso, setPeso] = useState("");
  const [altura, setAltura] = useState("");
  const [imc, setImc] = useState(null);
  const [classificacao, setClassificacao] = useState("");
  const [dica, setDica] = useState("");
  const [diferencaPeso, setDiferencaPeso] = useState("");
  const [modalVisible, setModalVisible] = useState(false);
  const [corClassificacao, setCorClassificacao] = useState("#6b5bff");

  const [snackVisible, setSnackVisible] = useState(false);
  const [snackMessage, setSnackMessage] = useState("");

  const calcularDiferencaPeso = (pesoAtual, alturaMetros, imcValor) => {
    const pesoMin = 18.5 * alturaMetros * alturaMetros;
    const pesoMax = 24.9 * alturaMetros * alturaMetros;

    if (imcValor < 18.5) {
      const ganhar = pesoMin - pesoAtual;
      return { mensagem: `Você precisa ganhar ${ganhar.toFixed(1)} kg para atingir IMC 18.5.`, diferenca: ganhar };
    }
    if (imcValor > 24.9) {
      const perder = pesoAtual - pesoMax;
      return { mensagem: `Você precisa perder ${perder.toFixed(1)} kg para atingir IMC 24.9.`, diferenca: perder };
    }
    return { mensagem: "Você está no peso ideal!", diferenca: 0 };
  };

  const gerarClassificacaoEDica = (valorIMC) => {
    if (valorIMC < 18.5) return { classificacao: "Abaixo do peso", dica: "Inclua mais calorias e proteínas. Consulte nutricionista.", cor: "#4da6ff" };
    else if (valorIMC < 24.9) return { classificacao: "Peso normal", dica: "Ótimo! Mantenha alimentação equilibrada e exercícios.", cor: "#28c76f" };
    else if (valorIMC < 29.9) return { classificacao: "Sobrepeso", dica: "Reduza ultraprocessados e aumente fibras.", cor: "#ffb020" };
    else if (valorIMC < 34.9) return { classificacao: "Obesidade grau I", dica: "Acompanhe alimentação e exercícios com profissional.", cor: "#ff8a65" };
    else if (valorIMC < 39.9) return { classificacao: "Obesidade grau II", dica: "Procure médico e nutricionista.", cor: "#ff7043" };
    else return { classificacao: "Obesidade grau III (grave)", dica: "Acompanhamento médico especializado recomendado.", cor: "#ff4d4f" };
  };

  const validarENotificar = (mensagem) => {
    setSnackMessage(mensagem);
    setSnackVisible(true);
  };

  const handleCalcularIMC = () => {
    let pesoNum = parseFloat(peso.replace(",", "."));
    let alturaNum = parseFloat(altura.replace(",", "."));

    if (!peso || !altura) return validarENotificar("Preencha todos os campos!");
    if (isNaN(pesoNum) || isNaN(alturaNum)) return validarENotificar("Digite apenas números válidos!");
    if (pesoNum <= 0) return validarENotificar("O peso precisa ser maior que zero!");
    if (alturaNum <= 0) return validarENotificar("A altura precisa ser maior que zero!");
    if (alturaNum > 3) alturaNum = alturaNum / 100;
    if (alturaNum > 3) return validarENotificar("A altura máxima permitida é de 3 metros!");

    const valorIMC = pesoNum / (alturaNum * alturaNum);
    if (!isFinite(valorIMC)) return validarENotificar("Não foi possível calcular o IMC.");

    const imcFormatado = valorIMC.toFixed(2);
    const { classificacao, dica, cor } = gerarClassificacaoEDica(valorIMC);
    const diff = calcularDiferencaPeso(pesoNum, alturaNum, valorIMC);

    setImc(imcFormatado);
    setClassificacao(classificacao);
    setDica(dica);
    setDiferencaPeso(diff.mensagem);
    setCorClassificacao(cor);
    setModalVisible(true);
  };

  const tabela = [
    { faixa: "Menor que 18.5", nome: "Abaixo do peso" },
    { faixa: "18.5 - 24.9", nome: "Peso normal" },
    { faixa: "25 - 29.9", nome: "Sobrepeso" },
    { faixa: "30 - 34.9", nome: "Obesidade grau I" },
    { faixa: "35 - 39.9", nome: "Obesidade grau II" },
    { faixa: "40 ou mais", nome: "Obesidade grau III" },
  ];

  return (
    <PaperProvider>
      <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === "ios" ? "padding" : undefined}>
        <ScrollView contentContainerStyle={styles.container}>
          <Text style={styles.logo}>HappyBody</Text>
          <Text style={styles.sub}>Calculadora de IMC</Text>

          <Card style={styles.card}>
            <Card.Content>
              <TextInput label="Peso" placeholder="Ex: 68.5" keyboardType="numeric" value={peso} onChangeText={setPeso} mode="outlined" style={styles.input} />
              <TextInput label="Altura" placeholder="Ex: 170" keyboardType="numeric" value={altura} onChangeText={setAltura} mode="outlined" style={styles.input} />
              <Button mode="contained" onPress={handleCalcularIMC} style={styles.button}>
                Calcular
              </Button>
            </Card.Content>
          </Card>

          <Portal>
            <Modal visible={modalVisible} onDismiss={() => setModalVisible(false)} contentContainerStyle={styles.modalBox}>
              <ScrollView contentContainerStyle={styles.modalContent}>
                <View style={styles.header}>
                  <View style={[styles.badge, { backgroundColor: corClassificacao }]} />
                  <Text style={styles.modalTitle}>Resultado</Text>
                </View>
                <Text style={styles.imcText}>Seu IMC: <Text style={styles.imcNumber}>{imc}</Text></Text>
                <Text style={[styles.classText, { color: corClassificacao }]}>{classificacao}</Text>
                <Text style={styles.diffText}>{diferencaPeso}</Text>
                <Text style={styles.helpText}>{dica}</Text>

                <View style={styles.table}>
                  {tabela.map((row, idx) => {
                    const isActive = row.nome === classificacao;
                    return (
                      <View key={idx} style={[styles.tableRow, isActive ? styles.rowActive : null]}>
                        <Text style={[styles.tableCell, isActive && styles.activeText]}>{row.faixa}</Text>
                        <Text style={[styles.tableCell, isActive && styles.activeText]}>{row.nome}</Text>
                      </View>
                    );
                  })}
                </View>

                <Button mode="contained" onPress={() => setModalVisible(false)} style={styles.closeButton}>
                  Fechar
                </Button>
              </ScrollView>
            </Modal>
          </Portal>

          <Snackbar visible={snackVisible} onDismiss={() => setSnackVisible(false)} duration={2500} style={{ backgroundColor: "#5a40ff" }}>
            {snackMessage}
          </Snackbar>
        </ScrollView>
      </KeyboardAvoidingView>
    </PaperProvider>
  );
}

const styles = StyleSheet.create({
  container: { flexGrow: 1, backgroundColor: "#f5f7ff", alignItems: "center", paddingHorizontal: 20, paddingTop: 60 },
  logo: { fontSize: 34, fontWeight: "800", color: "#5a40ff", letterSpacing: 0.5 },
  sub: { fontSize: 16, color: "#6b6f82", marginBottom: 20 },
  card: { width: "100%", borderRadius: 16, padding: 10, marginBottom: 20 },
  input: { marginBottom: 12, backgroundColor: "#f7f8ff" },
  button: { marginTop: 6, backgroundColor: "#5a40ff" },
  modalBox: { backgroundColor: "#fff", borderRadius: 18, padding: 16, margin: 20 },
  modalContent: { alignItems: "center", paddingBottom: 12 },
  header: { flexDirection: "row", alignItems: "center", marginBottom: 12 },
  badge: { width: 12, height: 12, borderRadius: 6, marginRight: 10 },
  modalTitle: { fontSize: 20, fontWeight: "700", color: "#222" },
  imcText: { fontSize: 18, marginTop: 6, color: "#444" },
  imcNumber: { fontWeight: "800", color: "#111", fontSize: 18 },
  classText: { fontSize: 18, fontWeight: "700", marginTop: 8 },
  diffText: { fontSize: 15, fontWeight: "600", marginTop: 8, color: "#333", textAlign: "center" },
  helpText: { fontSize: 14, color: "#666", textAlign: "center", marginVertical: 12, paddingHorizontal: 6 },
  table: { width: "100%", borderRadius: 12, overflow: "hidden", borderWidth: 1, borderColor: "#eef0ff", marginTop: 8, marginBottom: 14 },
  tableRow: { flexDirection: "row", justifyContent: "space-between", paddingVertical: 12, paddingHorizontal: 14, backgroundColor: "#fff" },
  rowActive: { backgroundColor: "#f6f0ff" },
  tableCell: { fontSize: 14, color: "#333", flex: 1 },
  activeText: { fontWeight: "800", color: "#5a40ff" },
  closeButton: { marginTop: 6, alignSelf: "center" },
});
